const $=selector=>document.querySelector(selector);
const app=$('#app'),dialog=$('#dialog');
const configuredBase=document.querySelector('meta[name="wai-base"]')?.content||'';
const base=configuredBase.startsWith('__')?'':configuredBase.replace(/\/$/,'');
const appURL=path=>base+path;
const appPath=location.pathname.slice(base.length)||'/';
const initialParams=new URLSearchParams(location.search);
const state={user:null,csrf:null,data:null,catalog:null,audience:initialParams.get('mode')==='agent'?'agent':'human',view:initialParams.has('order')||initialParams.get('view')==='servers'?'servers':initialParams.get('view')==='help'?'help':'new',purpose:'agent',consent:false,consentError:'',busy:false,selectedPaymentMethod:null,mode:{provider:'emulator',payments:'emulator',payment_live:false},error:'',fingerprint:'',auth:{magic_link:false},apiKeys:null,keysError:''};
const labels={agent:'Бот или агент',site:'Сайт',clean:'Приложение'};
const descriptions={agent:'Подготовим сервер. Самого бота или агента вы установите сами.',site:'Подготовим сервер. Останется загрузить сайт и настроить домен.',clean:'Полный доступ к серверу. Установите нужные программы и настройте его под себя.'};
const statuses={paid:'Оплата получена',creating:'Создаём сервер',configuring:'Настраиваем',checking:'Проверяем доступ',ready:'Готов к работе',overdue:'Пора продлить',unknown:'Проверяем создание',attention:'Нужна проверка',rejected:'Создание задерживается',deleting:'Удаляем',deleted:'Удалён'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(kind,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${{
  plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',external:'<path d="M8 5H5v14h14v-3M13 5h6v6M10 14l9-9"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V4H4v12h4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',key:'<circle cx="8" cy="9" r="4"/><path d="m11 12 8 8m-4-4 3-3m-1 5 3-3"/>',server:'<rect x="4" y="3" width="16" height="7" rx="2"/><rect x="4" y="14" width="16" height="7" rx="2"/><path d="M8 6.5h.01M8 17.5h.01M12 6.5h5M12 17.5h5"/>',agent:'<rect x="4" y="7" width="16" height="13" rx="4"/><path d="M12 3v4M8 12h.01M16 12h.01M9 16h6"/>',site:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M3 9h18M7 6.5h.01M10 6.5h.01M7 13h5m-5 3h9"/>',clean:'<path d="m5 7 5 5-5 5m8 0h6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>'
}[kind]||''}</svg>`;
const brand=()=>`<a href="${appURL('/')}" class="brand" aria-label="OpenStrudel · Серверы — главная"><picture><source srcset="${appURL('/strudel-graphite.png')}" media="(prefers-color-scheme: dark)"><img src="${appURL('/strudel-cream.png')}" width="29" height="29" alt=""></picture>OpenStrudel <span>Серверы</span></a>`;
const plan=()=>state.catalog?.plan;
function money(amount,currency=plan()?.currency||'usd') {
  if(!Number.isFinite(Number(amount)))return 'Цена недоступна';
  if(String(currency).toLowerCase()==='usdt')return new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(amount/100)+' USDT';
  return new Intl.NumberFormat('ru-RU',{style:'currency',currency:String(currency).toUpperCase(),maximumFractionDigits:amount%100?2:0}).format(amount/100);
}
const date=n=>n?new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(n).replace(/ г\.$/,''):'После готовности';
const period=()=>plan()?.period_days||30;
function paymentMethods(){return state.catalog?.payment_methods?.filter(m=>m.available!==false)||[{id:state.mode.payments==='stripe_test'?'card':'test',label:'Тестовая оплата',amount:plan()?.amount,currency:plan()?.currency||'usd',test:!state.mode.payment_live}];}
function selectedMethod(){return paymentMethods().find(m=>m.id===state.selectedPaymentMethod)||paymentMethods()[0];}
function quote(){const m=selectedMethod();return {amount:m?.amount??plan()?.amount,currency:m?.amount!=null?m.currency:plan()?.currency};}
const quoteLabel=()=>{const q=quote();return money(q.amount,q.currency);};
function methodSelect(id='payment-method'){
  const methods=paymentMethods();if(methods.length<2)return '';
  const titles={card:'Карта',crypto:'USDT',test:'Тест',rub:'Карта · ₽'};
  return `<fieldset class="payment-set"><legend class="field-caption">Способ оплаты</legend><div class="payment-options">${methods.map(m=>`<label class="payment-option"><input id="${id}-${esc(m.id)}" type="radio" name="payment_method" value="${esc(m.id)}" ${m.id===selectedMethod()?.id?'checked':''}><span>${esc(titles[m.id]||m.label)}</span></label>`).join('')}</div></fieldset>`;
}
function modeMessage(){
  if(state.mode.provider==='emulator'&&!state.mode.payment_live)return 'Демонстрация · без списаний и настоящих серверов';
  if(!state.mode.payment_live&&state.mode.payments==='wai_pay'&&plan()?.checkout_enabled===false)return '';
  if(!state.mode.payment_live)return 'Тестовая оплата · деньги не списываются';
  if(state.mode.provider==='emulator')return 'Серверы в режиме демонстрации · оплата через WAI Pay';
  return '';
}
let toastTimer,dialogReturnFocus,dialogReturnSelector;
function focusSelector(el){
  if(!el)return null;if(el.id)return '#'+CSS.escape(el.id);
  if(el.matches('summary')&&el.parentElement?.id)return '#'+CSS.escape(el.parentElement.id)+' > summary';
  const attrs=['data-server','data-do','data-action','data-view','data-pay','data-revoke'].filter(a=>el.hasAttribute(a));
  return attrs.length?attrs.map(a=>'['+a+'="'+CSS.escape(el.getAttribute(a))+'"]') .join(''):null;
}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;toastTimer=setTimeout(()=>$('#toast').textContent='',4500);}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Скопировано.');}catch{toast('Не удалось скопировать. Выделите текст вручную.');}}
async function api(path,{method='GET',body,download=false}={}){
  const r=await fetch(appURL(path),{method,credentials:'same-origin',headers:{...(body!==undefined?{'Content-Type':'application/json'}:{}),...(state.csrf?{'X-CSRF-Token':state.csrf}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});
  if(!r.ok){let data;try{data=await r.json();}catch{data={error:'Не удалось получить ответ. Попробуйте ещё раз.'};}const e=Error(data.error||'Не удалось выполнить действие.');e.status=r.status;throw e;}
  return download?r.blob():r.status===204?{}:r.json();
}
async function load(){try{const d=await api('/api/v1/me');if(state.user?.id!==d.user.id){state.apiKeys=null;state.keysError='';}state.user=d.user;state.csrf=d.csrf;state.auth=d.auth||state.auth;state.data=d;state.mode={...state.mode,...d.mode};return true;}catch(e){if(e.status===401){state.user=null;state.csrf=null;state.data=null;state.apiKeys=null;return false;}throw e;}}
function render(){
  if(appPath.startsWith('/checkout/'))return renderCheckout();
  const focus=app.contains(document.activeElement)?focusSelector(document.activeElement):null;
  const openDetails=[...app.querySelectorAll('details[open][id]')].map(x=>x.id);
  const mode=state.audience,notice=modeMessage();
  app.innerHTML=`<header class="site-header">${brand()}<div class="audience" role="tablist" aria-label="Как вы хотите использовать OpenStrudel · Серверы"><button id="mode-human" role="tab" aria-selected="${mode==='human'}" aria-controls="audience-content" tabindex="${mode==='human'?0:-1}" data-mode="human">Для себя</button><button id="mode-agent" role="tab" aria-selected="${mode==='agent'}" aria-controls="audience-content" tabindex="${mode==='agent'?0:-1}" data-mode="agent">Для агента</button></div><div class="header-actions">${state.user?`<button class="text-btn" data-view="servers">Мои серверы</button><details id="account-menu" class="account-menu"><summary aria-label="Ваш аккаунт">${esc(state.user.email.slice(0,1).toUpperCase())}</summary><div class="account-popover"><p>${esc(state.user.email)}</p><button class="text-btn" data-action="password">Пароль</button><button class="text-btn" data-action="recovery">Код восстановления</button><button class="text-btn" data-action="export">Скачать данные аккаунта</button><button class="text-btn" data-action="logout">Выйти</button></div></details>`:'<button class="text-btn" data-action="login">Войти '+icon('arrow',16)+'</button>'}</div></header>${notice?`<p class="mode-note"><span class="dot" aria-hidden="true"></span>${esc(notice)}</p>`:''}<main tabindex="-1" class="main ${mode==='agent'&&state.view==='new'?'wide':''}" id="main">${state.error?`<div class="notice error" role="alert">${esc(state.error)}</div>`:''}<div id="audience-content" role="tabpanel" aria-labelledby="mode-${mode}">${state.view==='help'?helpView():state.view==='servers'?serversView():mode==='agent'?agentView():createView()}</div></main><footer class="site-footer"><span>WaiWai · Свой сервер, полный доступ</span><div class="footer-links"><button class="text-btn" data-view="help">Помощь и условия</button><a class="text-btn" href="mailto:hi@waiwai.is">Поддержка</a><a class="text-btn" href="${appURL('/llms.txt')}">API ${icon('external',13)}</a></div></footer>`;
  for(const id of openDetails){const el=document.getElementById(id);if(el instanceof HTMLDetailsElement)el.open=true;}
  if(focus)app.querySelector(focus)?.focus({preventScroll:true});
  state.fingerprint=JSON.stringify(state.data);
}
function createView(){
  const p=plan(),unavailable=p?.checkout_enabled===false||paymentMethods().length===0,disabled=state.busy||!p||unavailable;
  return `<section class="hero"><h1>Сервер для<br><span>вашей идеи.</span></h1><p>Выберите задачу. Подготовку возьмём на себя.</p></section>
  <section class="composer" aria-label="Выбор сервера">
    <fieldset class="purpose-set"><legend class="field-caption">Что запустим?</legend><div class="choices">${Object.keys(labels).map(k=>`<label class="choice"><input id="purpose-${k}" type="radio" name="purpose" value="${k}" ${state.purpose===k?'checked':''} aria-describedby="purpose-description">${icon(k,22)}<span class="choice-title">${labels[k]}</span><span class="choice-check">${icon('check',14)}</span></label>`).join('')}</div></fieldset>
    <p id="purpose-description" class="purpose-description">${descriptions[state.purpose]}</p>
    <div class="purchase">${methodSelect()}<div class="purchase-row"><div class="price" aria-live="polite" aria-atomic="true">${esc(quoteLabel())}<span>за ${period()} дней</span></div><p class="price-caption">С настройкой.<br>${state.mode.payment_live?'Без автосписаний.':'Тестовый режим, без списаний.'}</p></div>
    <div class="consent-block"><label class="consent"><input id="consent" type="checkbox" ${state.consent?'checked':''} aria-describedby="rental-note${state.consentError?' consent-error':''}" ${state.consentError?'aria-invalid="true"':''}><span>Принимаю условия аренды</span></label><p id="rental-note" class="rental-note">Продление вручную. Через 3 дня после окончания срока сервер и данные будут удалены, если его не продлить.</p>${state.consentError?`<p class="inline-error" id="consent-error" role="alert">${esc(state.consentError)}</p>`:''}</div>
    <button class="btn full" data-action="create" ${disabled?'disabled':''}>${state.busy?'Открываем оплату…':unavailable?'Пока недоступно':'Продолжить'} ${state.busy||unavailable?'':icon('arrow',18)}</button>
    <p class="next-step">${unavailable?'Новые заказы временно недоступны.':state.busy?'Заказ сохраняется. Дождитесь перехода.':state.user?'Далее — оплата на защищённой странице.':'Далее — аккаунт и оплата.'}</p></div>
    ${unavailable?'<p class="notice">'+esc(p?.checkout_message||'Не удалось подготовить оплату. Попробуйте позже.')+'</p>':''}
    <details id="plan-details" class="details"><summary>Что входит в стоимость</summary><dl class="spec-grid"><div><dt>Память</dt><dd>${p?esc(p.ram_mb/1024)+' ГБ':'—'}</dd></div><div><dt>Диск</dt><dd>${p?esc(p.disk_gb)+' ГБ SSD':'—'}</dd></div><div><dt>Расположение</dt><dd>${esc(p?.region||'—')}</dd></div><div><dt>Трафик</dt><dd>${p?esc(p.traffic_gb/1000)+' ТБ за период':'—'}</dd></div><div><dt>Процессор</dt><dd>1 ядро, общие ресурсы</dd></div><div><dt>Доступ</dt><dd>Свой IP и полный доступ по SSH</dd></div></dl><p>${state.purpose==='agent'?'Установим Docker. Сам агент, его подписки и ключи AI-сервисов не включены.':state.purpose==='site'?'Установим Nginx. Загрузка сайта, домен и HTTPS настраиваются отдельно.':'Вы получите чистый Linux. Программы для проекта устанавливаете сами.'}</p><p>${period()} дней начинаются, когда сервер готов. Автоматические копии ваших файлов не включены. Отдельный аккаунт у провайдера не нужен.</p><button class="link-btn" data-view="help">Все условия ${icon('arrow',15)}</button></details>
  </section>`;
}
function serversView(){
  if(!state.user)return `<section class="hero"><h1>Ваши серверы</h1></section><div class="empty">${icon('server',32)}<h2>Войдите в свой аккаунт</h2><p>Войдите, чтобы увидеть заказы и получить доступ к серверам.</p><button class="btn" data-action="login">Войти</button></div>`;
  const d=state.data,active=d.servers.filter(s=>s.state!=='deleted'),archived=d.servers.filter(s=>s.state==='deleted');
  const pending=d.orders.filter(o=>['draft','checkout','needs_refund','refunded'].includes(o.status));
  return `<div class="page-head"><div><h1>Ваши серверы</h1><p>Доступ, срок аренды и управление.</p></div><button class="text-btn" data-view="new">${icon('plus',17)} Новый сервер</button></div>${pending.map(o=>`<div class="order-row"><div><h2>${o.kind==='renewal'?'Продление сервера':esc(labels[o.purpose])}</h2><p>${o.status==='refunded'?'Платёж возвращён.':o.status==='needs_refund'?'Сервер не подготовлен. Поддержка проверяет возврат.':'Ожидает оплаты.'} · ${esc(money(o.amount,o.currency))}</p></div>${['needs_refund','refunded'].includes(o.status)?'':`<button class="btn secondary" data-pay="${esc(o.id)}">Продолжить оплату</button>`}</div>`).join('')}<div class="server-list">${active.length?active.map(serverCard).join(''):pending.length?'':`<div class="empty">${icon('server',34)}<h2>Здесь будет ваш первый сервер</h2><p>Выберите задачу, и мы подготовим сервер.</p><button class="btn" data-view="new">Выбрать задачу ${icon('arrow',17)}</button></div>`}</div>${archived.length?`<details id="archived-servers" class="details archive"><summary>Завершённые серверы · ${archived.length}</summary><div class="server-list">${archived.map(serverCard).join('')}</div></details>`:''}${active.length?'<p class="footnote">Продление вручную. Автоматических списаний нет.</p>':''}`;
}
function serverCard(s){
  const active=['ready','overdue'].includes(s.state),deleteAttention=s.operation?.state==='delete_attention',warning=['unknown','attention','rejected'].includes(s.state),stages=['paid','creating','configuring','checking'],at=stages.indexOf(s.state);
  let content='';
  if(active)content=`${s.mode==='emulator'?'<p class="notice">Демо-сервер: адрес учебный, подключиться по SSH нельзя.</p>':''}${s.cancel_at_end?`<p class="notice warn">Сервер и данные будут удалены ${date(s.paid_until)}. Сохраните копию заранее.</p>`:s.state==='overdue'?`<p class="notice warn">Оплаченный срок закончился. Продлите сервер или сохраните данные до ${date(s.paid_until+3*86400e3)}.</p>`:''}<div class="server-bottom"><div class="server-address">${s.mode==='emulator'?'Учебный адрес':'Адрес сервера'}<code>${esc(s.ip)}</code></div><button class="btn" data-server="${s.id}" data-do="${s.state==='overdue'&&!s.cancel_at_end?'renew':'key'}">${s.state==='overdue'&&!s.cancel_at_end?'Продлить сервер':'Получить доступ'} ${icon('arrow',16)}</button></div><details id="manage-${s.id}" class="details"><summary>Управление сервером</summary><div class="server-actions"><button class="text-btn" data-server="${s.id}" data-do="renew" ${s.cancel_at_end?'disabled':''}>Продлить на ${period()} дней</button><button class="text-btn" data-server="${s.id}" data-do="backup">Экспортировать файлы</button><button class="text-btn" data-server="${s.id}" data-do="cancel">${s.cancel_at_end?'Оставить сервер':'Удалить в конце срока'}</button></div><p>Вы управляете сервером полностью. Выключение Linux не завершает аренду.</p><p class="small">ID: <code>${esc(s.id)}</code></p><button class="text-btn danger-text" data-server="${s.id}" data-do="delete">Удалить сейчас</button></details>`;
  else if(s.error==='payment_refunded')content='<p class="notice">Платёж возвращён. Создание сервера остановлено. С вопросами по заказу напишите в поддержку.</p>';
  else if(deleteAttention)content=`<p class="notice warn">Провайдер пока не подтвердил удаление. Проверим состояние сервера ещё раз.</p><button class="btn secondary" data-server="${s.id}" data-do="retry">Проверить и продолжить удаление</button>`;
  else if(s.state==='deleting')content='<p class="status-copy">Останавливаем сервер и ждём подтверждения удаления. Это может занять несколько минут.</p>';
  else if(s.state==='deleted')content='<p class="status-copy">Удаление подтверждено. Доступ закрыт, данные удалены.</p>';
  else content=`<ol class="progress" aria-label="Подготовка сервера">${['Оплата','Создание','Настройка','Проверка'].map((label,i)=>`<li class="${i===at?'current':i<at||i===0?'done':''}" ${i===at?'aria-current="step"':''}>${label}</li>`).join('')}</ol>${warning?`<p class="notice warn">${s.state==='rejected'?'Сервер пока не создан. Заказ и оплата сохранены. Повторите проверку или напишите в поддержку.':'Проверяем состояние сервера у провайдера. Ваш заказ и оплата сохранены.'}</p><button class="btn secondary" data-server="${s.id}" data-do="retry">${s.state==='rejected'?'Попробовать снова':'Проверить ещё раз'}</button>`:`<p class="status-copy">${s.error?'Подготовка задерживается. Мы повторяем проверку.':'Подготовка продолжится, если закрыть страницу. Готовность появится здесь.'}</p>`}`;
  return `<section class="server-card" aria-label="${esc(labels[s.purpose])}"><div class="server-top"><div><h2>${esc(labels[s.purpose])}</h2><p class="server-sub">${active?'Оплачен до '+date(s.paid_until):s.id.slice(0,8)}</p></div><span class="status ${deleteAttention||warning||s.state==='overdue'?'warn':active?'':'wait'}"><span class="dot" aria-hidden="true"></span>${esc(s.error==='payment_refunded'?'Создание отменено':deleteAttention?'Нужна проверка удаления':statuses[s.state]||s.state)}</span></div>${content}</section>`;
}
function apiExample(){return `curl ${location.origin}${appURL('/api/v1/orders')} \\\n  -H "Authorization: Bearer $WAI_VDS_KEY" \\\n  -H "Content-Type: application/json" \\\n  -d '{\n    "purpose": "agent",\n    "payment_method": "${selectedMethod()?.id||'test'}",\n    "idempotency_key": "my-agent-001",\n    "consent": true\n  }'`;}
function agentInstruction(){return `Прочитай ${location.origin}${appURL('/llms.txt')}. Подключи OpenStrudel · Серверы через его API, используя мой API-ключ. Сначала покажи мне назначение сервера, полную цену и условия. После моего согласия создай заказ и передай мне ссылку на оплату. Не выдавай тестовый сервер за настоящий.`;}
function agentView(){return `<section class="hero agent-hero"><h1>Тот же сервер.<br><span>Через API.</span></h1><p>Поручите агенту заказ и настройку.<br>Оплату подтверждаете вы.</p><div class="agent-actions"><button class="btn" data-action="api">Создать API-ключ ${icon('key',17)}</button><button class="text-btn" data-action="copy-instruction">Скопировать инструкцию ${icon('copy',15)}</button></div></section><nav class="docs-links" aria-label="Документация API"><a href="${appURL('/llms.txt')}">Для агента · llms.txt ${icon('external',14)}</a><a href="${appURL('/openapi.json')}">OpenAPI ${icon('external',14)}</a></nav><section class="code-panel" aria-label="Пример создания заказа"><div class="code-header"><span>Создать заказ</span><button class="text-btn" data-action="copy-example" aria-label="Скопировать пример создания заказа">${icon('copy',15)} Копировать</button></div><pre class="code-block"><code>${esc(apiExample())}</code></pre></section><div class="api-explain"><p>${esc(quoteLabel())} за ${period()} дней. Получите согласие на цену перед <code>consent: true</code>.</p><p>Ключ открывает доступ только к вашему аккаунту. Храните его в секретах приложения.</p></div><details id="api-flow" class="details"><summary>От заказа до подключения</summary><ol class="api-flow"><li><code>POST /api/v1/orders</code> — создайте заказ.</li><li><code>POST /api/v1/orders/{id}/checkout</code> — получите ссылку и передайте её человеку для оплаты.</li><li><code>GET /api/v1/orders/{id}</code> — дождитесь <code>server_id</code>. Подготовка начинается после подтверждения оплаты.</li><li><code>GET /api/v1/servers/{id}</code> — проверьте готовность. <code>POST /api/v1/servers/{id}/access</code> — скачайте SSH-ключ.</li></ol><p>Если ответ потерялся, повторите запрос с тем же <code>idempotency_key</code>. Для нового заказа используйте новый ключ.</p><p>Доступные способы оплаты и цену читайте в <code>GET /api/v1/catalog</code>.</p></details><details id="api-keys" class="details"><summary>Ваши API-ключи</summary>${state.user?keyList():`<p>Войдите, чтобы создавать и отзывать ключи.</p><button class="text-btn" data-action="login">Войти ${icon('arrow',15)}</button>`}</details><details id="sandbox-details" class="details"><summary>Как протестировать без оплаты</summary><p>Для специально выданного тестового ключа с разрешением <code>sandbox:provision</code> доступен <code>POST /api/v1/agent/servers</code>. Это эмулятор: <code>billable: false</code>, без настоящего сервера и SSH.</p><p>Обычный API-ключ работает с оплаченными заказами. За тестовым доступом обратитесь в поддержку.</p></details>`;}
function keyList(){
  if(state.keysError)return `<p class="notice error">${esc(state.keysError)}</p><button class="text-btn" data-action="reload-keys">Повторить</button>`;
  if(state.apiKeys===null)return '<p>Загружаем ключи…</p>';
  const keys=state.apiKeys.filter(k=>!k.revoked);
  return keys.length?keys.map(k=>`<div class="key-row"><div><h3>${esc(k.name)}</h3><p><code>${esc(k.prefix)}…</code> · ${k.expires<Date.now()?'Срок истёк':'До '+date(k.expires)}</p><p>${esc((k.scopes||[]).join(', '))}</p></div><button class="text-btn danger-text" data-revoke="${esc(k.id)}">Отозвать</button></div>`).join(''):'<p>Активных ключей пока нет. Создайте отдельный ключ для каждого приложения.</p>';
}
async function loadKeys(){if(!state.user)return;const uid=state.user.id;try{const r=await api('/api/v1/api-keys');if(state.user?.id!==uid)return;state.apiKeys=r.keys;state.keysError='';}catch(e){if(state.user?.id!==uid)return;state.keysError=e.message;}render();}
function helpView(){const paymentText=state.mode.payment_live?'Оплата проходит на внешней платёжной странице. Данные карты не попадают в OpenStrudel · Серверы.':'Это тестовый режим оплаты: деньги не списываются.';return `<article class="article"><h1>Помощь и условия</h1><p>Об оплате, доступе и ваших данных.</p>${[
['Что я получу?','Отдельный сервер с Linux и публичным IP. Для агента подготовлен Docker, для сайта Nginx. Полный root-доступ позволяет установить свои программы. Провайдерский аккаунт принадлежит OpenStrudel · Серверы, отдельная регистрация у провайдера вам не нужна.'],
['Когда начинается оплаченный срок?',`${period()} дней отсчитываются с момента готовности сервера. ${paymentText} Полная цена и валюта выбранного способа видны до создания заказа. Банк может отдельно применить свою конвертацию, а криптокошелёк — комиссию сети. Доступность карты или сети определяет платёжный сервис. ${state.catalog?.tax_note||''}`],
['Как продлить или отменить?', 'Каждое продление вы подтверждаете отдельно. Автосписаний нет. При неоплате доступны ещё 3 дня после окончания срока, затем сервер и данные удаляются. При отмене в конце срока удаление происходит сразу по окончании оплаченного периода. Выключение Linux не прекращает оплату.'],
['Как подключиться?', 'В кабинете нажмите «Получить доступ». Подтвердите вход и скачайте личный SSH-ключ. Там же будет готовая команда для подключения. Ключ даёт полный доступ к серверу: храните его в личной папке. Пароль root не отправляется по почте.'],
['Как сохранить копию или переехать?', 'Внешние резервные копии не включены. В разделе управления есть команда экспорта папки проекта /srv/wai. Базы данных сначала выгрузите средствами приложения. Полный доступ позволяет сохранить и другие файлы. Перед удалением проверьте копию.'],
['А если создание задержится?', 'Заказ, оплата и попытка создания сохраняются. Если подготовка задерживается, проверяем состояние у провайдера. Повторное нажатие не создаёт второй сервер. Если платёж пришёл уже после начала удаления, поддержку подключаем для возврата.'],
['Как восстановить доступ?', 'Войдите по ссылке из письма. Если доступа к почте нет, используйте заранее сохранённый код восстановления через «Войти с паролем» → «Забыли пароль?». Код можно выпустить в меню аккаунта, подтвердив вход. После восстановления все прежние сеансы и ключи приложений отключаются.'],
['Кто оказывает услугу и куда обращаться?', 'Сервис предоставляет WaiWai, LLC. По вопросам оплаты, доступа и возврата напишите на hi@waiwai.is. Укажите email аккаунта и номер заказа. Пароли, код восстановления и личный SSH-ключ отправлять не нужно.'],
['Если оплата прошла, а сервер не выдан?', 'Мы проверяем платёж и выдачу по номеру заказа. Если выдать сервер не удалось, заказ передаётся оператору для возврата на исходный способ оплаты. Возврат не происходит мгновенно: срок зависит от платёжной системы. По вопросам уже оказанной услуги обратитесь в поддержку.'],
['Какие данные сохраняются?', 'Мы сохраняем email, сведения о заказах и оплате, действия с аккаунтом и настройки сервера. Пароль хранится как хеш, личный SSH-ключ — в зашифрованном виде. Письма со ссылками для входа отправляет Resend. Карту обрабатывает Stripe, криптоплатёж — Cryptomus через WAI Pay; сервер создаёт Kamatera. Эти сервисы получают данные, нужные для выполнения операции. Данные аккаунта можно скачать в меню; запрос по их удалению направьте в поддержку. Сведения, необходимые для учёта оплат, могут сохраняться после закрытия аккаунта.'],
['Есть ли ограничения?', 'Применяются правила инфраструктурного провайдера. Спам, атаки и нарушение чужих прав запрещены. CPU общий; резервные копии и установка самого AI-агента не включены. Ключи сторонних AI-сервисов вы добавляете на свой сервер самостоятельно.']
].map(([title,text],i)=>`<details id="help-${i}" class="details"><summary>${esc(title)}</summary><p>${esc(text)}</p></details>`).join('')}<button class="link-btn" data-view="new">К выбору сервера ${icon('arrow',16)}</button></article>`;}
function showDialog(html){if(!dialog.open){dialogReturnFocus=document.activeElement;dialogReturnSelector=focusSelector(dialogReturnFocus);}dialog.innerHTML=`<button class="close" aria-label="Закрыть">${icon('close',18)}</button>${html}`;if(!dialog.open)dialog.showModal();dialog.querySelector('.close').onclick=()=>dialog.close();const target=dialog.querySelector('input:not([readonly])')||dialog.querySelector('h2');if(target){if(target.tagName==='H2')target.tabIndex=-1;target.focus();}}
function showDialogError(error){const notice=dialog.querySelector('.dialog-error');if(notice){notice.textContent=error.message;notice.tabIndex=-1;notice.focus();}else toast(error.message);}
dialog.addEventListener('close',()=>{if(dialog.open)return;dialog.replaceChildren();const target=dialogReturnFocus?.isConnected?dialogReturnFocus:dialogReturnSelector?document.querySelector(dialogReturnSelector):null;target?.focus({preventScroll:true});});
function authDialog(mode='email',after){
  if(state.auth.magic_link&&['email','login','register'].includes(mode))return magicDialog(after);
  if(mode==='email')mode='login';
  mode=mode.replace('password-','');
  showDialog(`<h2 id="dialog-title">${mode==='register'?'Создать аккаунт':'Войти в OpenStrudel · Серверы'}</h2><p>${mode==='register'?'Здесь будут ваши серверы и доступ к ним.':'Войдите, чтобы продолжить.'}</p><form id="auth-form"><label class="field">Email<input type="email" name="email" autocomplete="email" required maxlength="254" inputmode="email"></label><label class="field">Пароль<input type="password" name="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="12" maxlength="256" required aria-describedby="password-hint"></label><div id="password-hint" class="field-help">Не менее 12 символов.</div><div class="dialog-error" role="alert"></div><button class="btn full" type="submit">${mode==='register'?'Создать аккаунт':'Войти'} ${icon('arrow',17)}</button></form><div class="auth-switch">${mode==='register'?'Уже есть аккаунт?':'Первый раз здесь?'} <button class="text-btn" id="switch-auth">${mode==='register'?'Войти':'Создать аккаунт'}</button></div>${mode==='login'?'<button class="text-btn" id="forgot-password">Забыли пароль?</button>':''}${state.auth.magic_link?'<button class="text-btn" id="email-auth">Войти по ссылке из письма</button>':''}`);
  $('#switch-auth').onclick=()=>authDialog(mode==='register'?'password-login':'password-register',after);
  if($('#email-auth'))$('#email-auth').onclick=()=>magicDialog(after);
  if($('#forgot-password'))$('#forgot-password').onclick=()=>recoverAccountDialog();
  $('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{const data=new FormData(e.target),result=await api('/api/v1/auth/'+mode,{method:'POST',body:{email:data.get('email'),password:data.get('password')}});state.csrf=result.csrf;if(result.recovery_code){showRecoveryCode(result.recovery_code,async()=>{try{await load();render();if(after)await after();}catch(error){state.error=error.message;render();}});return;}await load();dialog.close();render();if(after)await after();}catch(error){showDialogError(error);}finally{button.disabled=false;}};
}
function magicDialog(after){
  showDialog('<h2 id="dialog-title">Войти по email</h2><p>Пришлём ссылку для входа. Пароль не нужен.</p><form id="magic-form"><label class="field">Email<input name="email" type="email" autocomplete="email" inputmode="email" maxlength="254" required></label><div class="dialog-error" role="alert"></div><button class="btn full" type="submit">Получить ссылку '+icon('arrow',17)+'</button></form><button class="text-btn" id="password-auth">Войти с паролем</button>');
  $('#password-auth').onclick=()=>authDialog('password-login',after);
  $('#magic-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{const email=new FormData(form).get('email');await api('/api/v1/auth/magic-link/request',{method:'POST',body:{email,return_view:state.view==='new'?'new':state.audience==='agent'?'agent':'servers'}});showDialog(`<h2 id="dialog-title">Проверьте почту.</h2><p>Ссылка для входа отправлена на <strong>${esc(email)}</strong>.</p><p>Откройте письмо в этом браузере в течение 10 минут. Если письма нет, проверьте спам.</p><div class="dialog-error" role="alert"></div><button class="btn full" id="magic-done">Я вошёл. Продолжить</button><button class="text-btn" id="magic-again" disabled>Отправить ещё раз через минуту</button>`);const again=$('#magic-again');setTimeout(()=>{again.disabled=false;again.textContent='Отправить ещё раз';},60000);again.onclick=()=>magicDialog(after);$('#magic-done').onclick=async()=>{try{if(!await load())throw Error('Сначала подтвердите вход по ссылке из письма.');dialog.close();render();if(after)await after();}catch(error){showDialogError(error);}};}catch(error){showDialogError(error);}finally{button.disabled=false;}};
}
function identityFields(force=false,emailOnly=false){
  if(!state.auth.magic_link)return '<label class="field">Ваш пароль<input name="password" type="password" autocomplete="current-password" required></label>';
  return `<div class="identity-fields">${!force&&state.auth.magic_fresh_until>Date.now()?'<p class="field-help">Вход подтверждён.</p>':'<p class="field-help">Подтвердите вход, чтобы продолжить.</p><button type="button" class="text-btn" data-magic-reauth>Получить ссылку на email</button><p class="field-help" data-identity-notice role="status"></p>'+(emailOnly?'':'<details class="details"><summary>Подтвердить паролем</summary><label class="field">Ваш пароль<input name="password" type="password" autocomplete="current-password"></label></details>')}</div>`;
}
async function confirmOwner(form){
  try{await api('/api/v1/auth/reauth',{method:'POST',body:{password:new FormData(form).get('password')||undefined}});}
  catch(error){if(state.auth.magic_link&&error.status===403){const fields=form.querySelector('.identity-fields');if(fields)fields.outerHTML=identityFields(true);}throw error;}
}
function passwordDialog(){
  if(!state.auth.magic_link){toast('Вход по письму сейчас недоступен.');return;}
  showDialog(`<h2 id="dialog-title">Пароль для входа</h2><p>Можно добавить пароль и входить любым удобным способом.</p><form id="password-form">${identityFields(false,true)}<label class="field">Новый пароль<input type="password" name="new_password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label class="field">Повторите пароль<input type="password" name="confirm_password" autocomplete="new-password" minlength="12" maxlength="256" required></label><div class="dialog-error" role="alert"></div><button class="btn full">Сохранить пароль</button></form>`);
  $('#password-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit],button.btn');button.disabled=true;try{const data=new FormData(form);if(data.get('new_password')!==data.get('confirm_password'))throw Error('Пароли не совпадают.');await api('/api/v1/auth/password',{method:'POST',body:{password:data.get('new_password')}});await load();dialog.close();render();toast('Пароль сохранён. Вход по ссылке тоже работает.');}catch(error){if(error.status===403){const fields=form.querySelector('.identity-fields');if(fields)fields.outerHTML=identityFields(true,true);}showDialogError(error);}finally{button.disabled=false;}};
}
function showRecoveryCode(code,after){
  showDialog(`<h2 id="dialog-title">Сохраните код восстановления</h2><p>Код поможет вернуть доступ, если забудете пароль. Мы покажем его один раз. Сохраните в менеджере паролей или скачайте.</p><label class="field">Код восстановления<input id="recovery-code" class="token-input" value="${esc(code)}" readonly autocomplete="off" spellcheck="false"></label><button class="btn full" id="download-recovery">Скачать код</button><button class="text-btn" data-copy-id="recovery-code">${icon('copy',15)} Скопировать</button><label class="consent"><input id="recovery-saved" type="checkbox"><span>Я сохранил код в безопасном месте</span></label><div class="dialog-error" role="alert"></div><button class="btn secondary full" id="recovery-continue">Продолжить ${icon('arrow',17)}</button>`);
  $('#download-recovery').onclick=async()=>{await saveBlob(new Blob(['OpenStrudel · Серверы — код восстановления\n\n'+code+'\n\nОткройте '+location.origin+appURL('/')+' и выберите «Войти» → «Забыли пароль?».\nКод даёт доступ к аккаунту. Не отправляйте его другим людям.\n'],{type:'text/plain;charset=utf-8'}),'openstrudel-recovery.txt');toast('Файл с кодом скачан.');};
  $('#recovery-continue').onclick=async()=>{if(!$('#recovery-saved').checked){showDialogError(Error('Сначала сохраните код восстановления.'));return;}dialog.close();render();if(after)await after();};
}
function recoverySettingsDialog(){
  showDialog(`<h2 id="dialog-title">Код восстановления</h2><p>Создайте новый код, если не сохранили прежний. Старый код сразу перестанет работать.</p><form id="recovery-settings">${identityFields()}<div class="dialog-error" role="alert"></div><button class="btn full" type="submit">Создать новый код</button></form>`);
  $('#recovery-settings').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit],button.btn');button.disabled=true;try{await confirmOwner(e.target);const result=await api('/api/v1/auth/recovery-code',{method:'POST',body:{password:new FormData(e.target).get('password')||undefined}});showRecoveryCode(result.recovery_code);}catch(error){showDialogError(error);}finally{button.disabled=false;}};
}
function recoverAccountDialog(){
  showDialog('<h2 id="dialog-title">Восстановить доступ</h2><p>Введите email и сохранённый код восстановления, затем задайте новый пароль.</p><form id="recover-account"><label class="field">Email<input type="email" name="email" autocomplete="email" required maxlength="254"></label><label class="field">Код восстановления<input name="recovery_code" required maxlength="256" autocomplete="off" autocapitalize="characters" spellcheck="false"></label><label class="field">Новый пароль<input type="password" name="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label class="field">Повторите пароль<input type="password" name="confirm_password" autocomplete="new-password" minlength="12" maxlength="256" required></label><p class="field-help">Прежние сеансы и ключи приложений будут отключены. Доступ по уже скачанному SSH-ключу останется прежним.</p><div class="dialog-error" role="alert"></div><button class="btn full" type="submit">Сохранить новый пароль</button></form>');
  $('#recover-account').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit],button.btn');button.disabled=true;try{const data=new FormData(e.target);if(data.get('password')!==data.get('confirm_password'))throw Error('Пароли не совпадают.');const result=await api('/api/v1/auth/recover',{method:'POST',body:{email:data.get('email'),recovery_code:data.get('recovery_code'),password:data.get('password')}});state.user=null;state.data=null;state.csrf=null;state.apiKeys=null;render();showRecoveryCode(result.recovery_code,()=>authDialog('login'));toast('Пароль изменён. Сохраните новый код и войдите снова.');}catch(error){showDialogError(error);}finally{button.disabled=false;}};
}
function confirmDialog(title,text,buttonText,action,{password=false,confirmId=null,danger=false,extra=''}={}){
  showDialog(`<h2 id="dialog-title">${esc(title)}</h2><p>${text}</p><form id="confirm-form">${extra}${password?identityFields():''}${confirmId?`<label class="field">Для подтверждения введите ID сервера<br><code>${esc(confirmId)}</code><input name="confirm" required autocomplete="off" spellcheck="false"></label>`:''}<div class="dialog-error" role="alert"></div><button class="btn full ${danger?'danger':''}" type="submit">${esc(buttonText)}</button></form>`);
  $('#confirm-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{if(password)await confirmOwner(e.target);await action(new FormData(e.target));dialog.close();await load();render();}catch(error){showDialogError(error);}finally{button.disabled=false;}};
}
async function create(){
  if(!state.consent){state.consentError='Подтвердите условия, чтобы продолжить.';render();$('#consent')?.focus();return;}
  if(!state.user){authDialog('register',create);return;}if(state.busy)return;
  state.busy=true;state.error='';render();
  try{const method=selectedMethod()?.id;const o=await api('/api/v1/orders',{method:'POST',body:{purpose:state.purpose,payment_method:method,idempotency_key:crypto.randomUUID(),consent:true}});await pay(o.id,o.payment_method||method);}
  catch(error){state.error=error.message;await load();state.view='servers';}finally{state.busy=false;render();}
}
async function pay(id,method){const o=state.data?.orders.find(o=>o.id===id);const result=await api(`/api/v1/orders/${id}/checkout`,{method:'POST',body:{method:o?.payment_method||method||selectedMethod()?.id}});location.assign(result.url);}
async function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function accessDialog(s){
  const filename='openstrudel-server-'+s.id.slice(0,8);
  showDialog(`<h2 id="dialog-title">Доступ к серверу</h2>${s.mode==='emulator'?'<p class="notice warn">Это демонстрация. Настоящего SSH-соединения по этому адресу нет.</p>':'<p>Сохраните личный ключ и подключитесь по готовой команде.</p>'}<form id="access-form">${identityFields()}<div class="dialog-error" role="alert"></div><button class="btn full" type="submit">${icon('download',17)} Скачать SSH-ключ</button></form><ol class="access-steps"><li>Откройте терминал в папке со скачанным ключом.</li><li>Ограничьте доступ к файлу: <code>chmod 600 ${filename}</code>.</li><li>Подключитесь командой ниже. Вход выполняется как root.</li></ol><pre id="ssh-command" class="secret">${esc(s.ssh)}</pre><button class="text-btn" data-copy-id="ssh-command">${icon('copy',15)} Скопировать команду</button><p class="small">Ключ даёт полный доступ. Не передавайте его посторонним. Аккаунт провайдера остаётся у OpenStrudel · Серверы.</p>`);
  $('#access-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit],button.btn');button.disabled=true;try{await confirmOwner(e.target);await saveBlob(await api(`/api/v1/servers/${s.id}/access`,{method:'POST',body:{},download:true}),filename);e.target.reset();toast('Ключ скачан. Дальше выполните команду подключения.');}catch(error){showDialogError(error);}finally{button.disabled=false;}};
}
function serverAction(id,what){
  const s=state.data?.servers.find(x=>x.id===id);if(!s)return;
  const post=(path,body={})=>api(`/api/v1/servers/${id}/${path}`,{method:'POST',body});
  if(what==='key')return accessDialog(s);
  if(what==='renew')return confirmDialog('Ещё '+period()+' дней',`Стоимость: <strong data-quote>${esc(quoteLabel())}</strong>. Новый срок до ${date(Math.max(Date.now(),s.paid_until)+period()*86400e3)}. Автосписаний нет.`,'Перейти к оплате',async f=>{const method=f.get('payment_method')||selectedMethod()?.id;const o=await post('renewals',{consent:true,payment_method:method});await pay(o.id,o.payment_method||method);},{extra:methodSelect('renewal-payment-method')});
  if(what==='cancel')return confirmDialog(s.cancel_at_end?'Оставить сервер?':'Удалить в конце срока?',s.cancel_at_end?'Сервер останется у вас. Для следующего периода потребуется отдельная оплата.':`Доступ останется до ${date(s.paid_until)}. После этого сервер и все данные будут удалены. Сохраните копию заранее.`,s.cancel_at_end?'Оставить сервер':'Удалить в конце срока',()=>post('cancellation',{cancel_at_end:!s.cancel_at_end}));
  if(what==='delete')return confirmDialog('Удалить сервер?','Данные будут удалены без возможности восстановления из OpenStrudel · Серверы. Неиспользованный срок автоматически не возвращается.','Удалить сервер',async f=>{await post('delete',{confirm:f.get('confirm')});},{password:true,confirmId:id,danger:true});
  if(what==='backup'){showDialog(`<h2 id="dialog-title">Экспортировать файлы</h2><p>После скачивания SSH-ключа выполните эту команду на своём компьютере. Архив появится в текущей папке.</p><pre id="backup-command" class="secret">${esc(s.ssh+" 'tar -C /srv -czf - wai' > wai-project.tar.gz")}</pre><button class="text-btn" data-copy-id="backup-command">${icon('copy',15)} Скопировать команду</button><p>Команда сохраняет только папку <code>/srv/wai</code>. Сначала выгрузите базы данных средствами приложения или остановите запись. Другие папки скопируйте отдельно. Проверьте архив перед удалением сервера.</p>${s.mode==='emulator'?'<p class="notice warn">В демонстрации эта команда не работает: настоящего SSH нет.</p>':''}`);return;}
  if(what==='retry')return run(async()=>{await post('retry');await load();render();toast('Проверка поставлена в очередь.');});
}
function keyDialog(){
  if(!state.user){authDialog('register',keyDialog);return;}
  showDialog(`<h2 id="dialog-title">Создать API-ключ</h2><p>Ключ позволит агенту управлять вашими серверами. Оплату вы подтверждаете отдельно.</p><form id="key-form"><label class="field">Название приложения<input name="name" value="Мой агент" maxlength="80" required autocomplete="off"></label>${identityFields()}<div class="field-help">Ключ действует 30 дней. Его можно отозвать в любой момент.</div><div class="dialog-error" role="alert"></div><button class="btn full" type="submit">Создать ключ</button></form>`);
  $('#key-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit],button.btn');button.disabled=true;try{await confirmOwner(e.target);const data=new FormData(e.target),result=await api('/api/v1/api-keys',{method:'POST',body:{name:data.get('name'),password:data.get('password')||undefined,expires_days:30}});state.apiKeys=null;showDialog(`<h2 id="dialog-title">Сохраните API-ключ</h2><p>Мы покажем его один раз. Сохраните в секретах приложения. Не отправляйте ключ в общий чат.</p><label class="field">API-ключ<input id="new-api-key" class="token-input" type="text" value="${esc(result.token)}" readonly autocomplete="off" spellcheck="false"></label><button class="btn full" data-copy-id="new-api-key">${icon('copy',17)} Скопировать ключ</button><p class="small">Срок действия: ${date(result.key?.expires)}. Доступ можно отозвать в разделе «Ваши API-ключи».</p>`);await loadKeys();}catch(error){showDialogError(error);}finally{button.disabled=false;}};
}
async function run(fn){try{await fn();}catch(error){state.error=error.message;render();}}
function navigate(view=state.view,audience=state.audience,{push=true}={}){state.view=view;state.audience=audience;state.error='';if(push){const p=new URLSearchParams();if(audience==='agent')p.set('mode','agent');if(view!=='new')p.set('view',view);history.pushState({},'',appURL('/')+(p.size?'?'+p:''));}render();if(push)window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);navigate(p.get('view')==='help'?'help':p.get('view')==='servers'||p.has('order')?'servers':'new',p.get('mode')==='agent'?'agent':'human',{push:false});});
document.addEventListener('change',e=>{if(e.target.name==='purpose'){state.purpose=e.target.value;render();}if(e.target.id==='consent'){state.consent=e.target.checked;if(state.consentError){state.consentError='';render();}}if(e.target.name==='payment_method'){state.selectedPaymentMethod=e.target.value;state.consent=false;state.consentError='';if(dialog.open)dialog.querySelectorAll('[data-quote]').forEach(el=>el.textContent=quoteLabel());else render();}});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[role="tab"][data-mode]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const mode=e.key==='Home'?'human':e.key==='End'?'agent':tab.dataset.mode==='human'?'agent':'human';navigate('new',mode);$('#mode-'+mode).focus();});
document.addEventListener('toggle',e=>{if(e.target.id==='api-keys'&&e.target.open&&state.user&&state.apiKeys===null&&!state.keysError)loadKeys();},true);
document.addEventListener('click',e=>{
  const emailConfirm=e.target.closest('[data-magic-reauth]');if(emailConfirm){const form=emailConfirm.closest('form'),notice=form.querySelector('[data-identity-notice]');emailConfirm.disabled=true;api('/api/v1/auth/magic-link/request',{method:'POST',body:{context:'reauth'}}).then(()=>{notice.textContent='Письмо отправлено. Подтвердите вход в этом браузере, затем вернитесь сюда и продолжите.';}).catch(error=>{notice.textContent=error.message;}).finally(()=>setTimeout(()=>emailConfirm.disabled=false,60000));return;}
  const mode=e.target.closest('[data-mode]');if(mode){navigate('new',mode.dataset.mode);$('#mode-'+mode.dataset.mode)?.focus();return;}
  const view=e.target.closest('[data-view]');if(view){navigate(view.dataset.view,view.dataset.view==='servers'?'human':state.audience);$('#main')?.focus({preventScroll:true});return;}
  const server=e.target.closest('[data-server]');if(server){serverAction(server.dataset.server,server.dataset.do);return;}
  const payButton=e.target.closest('[data-pay]');if(payButton){payButton.disabled=true;run(()=>pay(payButton.dataset.pay)).finally(()=>payButton.disabled=false);return;}
  const copy=e.target.closest('[data-copy-id]');if(copy){const el=document.getElementById(copy.dataset.copyId);copyText(el?.value??el?.textContent??'');return;}
  const revoke=e.target.closest('[data-revoke]');if(revoke){confirmDialog('Отозвать ключ?','Приложение сразу потеряет доступ к API. Серверы продолжат работать.','Отозвать ключ',async()=>{await api('/api/v1/api-keys/'+encodeURIComponent(revoke.dataset.revoke),{method:'DELETE',body:{}});await loadKeys();},{danger:true});return;}
  const action=e.target.closest('[data-action]')?.dataset.action;
  if(action==='password')passwordDialog();
  if(action==='create')create();if(action==='login')authDialog('login');if(action==='api')keyDialog();if(action==='recovery')recoverySettingsDialog();
  if(action==='copy-example')copyText(apiExample());if(action==='copy-instruction')copyText(agentInstruction());if(action==='reload-keys')loadKeys();
  if(action==='export')run(async()=>saveBlob(await api('/api/v1/account/export',{download:true}),'openstrudel-servers.json'));
  if(action==='logout')run(async()=>{await api('/api/v1/auth/logout',{method:'POST',body:{}});state.user=null;state.data=null;state.csrf=null;state.apiKeys=null;navigate('new');});
});
function renderCheckout(){
  const id=appPath.split('/')[2],o=state.data?.orders.find(o=>id==='cs_test_'+o.id||new RegExp('^cs_test_'+o.id+'_g[0-9]+$').test(id));
  if(!state.user){app.innerHTML=`<main class="checkout" id="main">${brand()}<h1>Войдите для оплаты</h1><p>Заказ доступен только его владельцу.</p><div class="checkout-actions"><button class="btn" data-action="login">Войти</button></div></main>`;return;}
  if(!o){app.innerHTML=`<main class="checkout" id="main"><h1>Платёж не найден</h1><p>Откройте оплату заново из своего кабинета.</p><a class="link-btn" href="${appURL('/?view=servers')}">В кабинет ${icon('arrow',16)}</a></main>`;return;}
  app.innerHTML=`<main class="checkout" id="main">${brand()}<span class="status warn">Тестовая оплата</span><h1>${o.kind==='renewal'?'Продление сервера':'Ваш сервер'}</h1><p>${esc(labels[o.purpose])} · ${period()} дней</p><div class="price">${esc(money(o.amount,o.currency))}</div><p class="notice">Деньги не списываются. Данные карты не нужны. Кнопка ниже проверит весь путь заказа в эмуляторе.</p><div class="dialog-error" role="alert"></div><div class="checkout-actions"><button class="btn" data-result="success">Подтвердить тестовую оплату ${icon('arrow',17)}</button><button class="btn secondary" data-result="cancel">Отменить</button></div><details class="details"><summary>Проверить отклонённый платёж</summary><button class="text-btn" data-result="fail">Имитировать отказ</button></details><a class="text-btn" href="${appURL('/?view=servers')}">Вернуться без оплаты</a></main>`;
  app.querySelectorAll('[data-result]').forEach(button=>button.onclick=async()=>{app.querySelectorAll('[data-result]').forEach(b=>b.disabled=true);try{const result=await api('/checkout/'+id+'/result',{method:'POST',body:{result:button.dataset.result}});location.assign(result.return_url);}catch(error){$('.dialog-error').textContent=error.message;app.querySelectorAll('[data-result]').forEach(b=>b.disabled=false);}});
}
await run(async()=>{state.auth=await api('/api/v1/auth/options');state.catalog=await api('/api/v1/catalog');state.mode={...state.mode,...state.catalog.mode};state.selectedPaymentMethod=selectedMethod()?.id;await load();const result=initialParams.get('payment');if(result==='fail'||result==='cancel'||result==='cancelled')state.error=result==='fail'?'Платёж отклонён. Можно повторить оплату сохранённого заказа.':'Оплата отменена. Заказ сохранён.';render();if(initialParams.get('login')==='email'&&!state.user)authDialog();});
setInterval(async()=>{if(!state.user||state.view!=='servers'||document.hidden||dialog.open||appPath.startsWith('/checkout/'))return;try{await load();const next=JSON.stringify(state.data);if(next!==state.fingerprint){state.fingerprint=next;render();}}catch{}},2500);
